// resetsPen reports whether the SGR sequences of tail, which follows a styling
// one, end on a reset, the last of them being `ESC [ m` or `ESC [ 0 m`.
func resetsPen(tail string) bool {
	k := strings.LastIndexByte(tail, 0x1b)
	if k < 0 {
		return false
	}
	seq := tail[k:]
	return strings.HasPrefix(seq, "\x1b[m") || strings.HasPrefix(seq, "\x1b[0m")
}

